import logging
import os.path

import requests

from ta_ue_plugin_android.uepc import utils
from ta_ue_plugin_android.uepc.ue_manager_exceptions import InvalidServerResponseException, \
    NoSuchVersionOnServerException, UeManagerApkUnavailableException, UeManagerApkUpdateException, NetworkException

ARTIFACTORY_URL = 'https://artifactory-espoo1.ext.net.nokia.com/artifactory'
ARTIFACTORY_REPO = 'mn-android-apk'
ARTIFACTORY_AQL_SUFFIX = 'api/search/aql'
ARTIFACTORY_USER = 'ca_5gauto'
ARTIFACTORY_PASSWD = '5Gauto123'
ARTIFACTORY_DEBUG_AQL_FRAGMENT = ' "path":{"$match": "debug"},'
UE_MANAGER_APK_NAME = 'UeManager.apk'
UE_MANAGER_NOT_INSTALLED = 'UeManager not installed'
UE_MANAGER_PACKAGE = 'com.nokia.syve.uemanager.mobile'
UE_MANAGER_NAME_PREFIX = 'UeManager-vc'
ARTIFACTORY_AQL_GET_NEWEST_QUERY = 'items.find({{"repo": {{"$eq": "{REPO}"}},{DEBUG_PATH} "name": {{"$match":"UeManager-vc-*-vn-' \
                                   '{VERSION}.apk"}}}}).include("name", "repo", "path", "created").sort({{"$desc": ' \
                                   '["created"]}}).limit(1)'
ARTIFACTORY_AQL_GET_ALL_QUERY = 'items.find({{"repo": {{"$eq": "{REPO}"}},{DEBUG_PATH} "name": {{"$match":"UeManager-vc-*-vn-*.' \
                                'apk"}}}}).include("name", "repo", "path", "created").sort({{"$desc": ["created"]}})'
NAA_APK_NAME = 'NokiaAndroidApplication.apk'
NAA_NOT_INSTALLED = 'NokiaAndroidApplication not installed'
NAA_PACKAGE = 'com.nokia.android.application'
NAA_NAME_PREFIX = 'NokiaAndroidApplication-vc'
ARTIFACTORY_AQL_GET_NEWEST_NAA_QUERY = 'items.find({{"repo": {{"$eq": "{REPO}"}},{DEBUG_PATH}  "name": ' \
                                       '{{"$match":"NokiaAndroidApplication-vc-*-vn-' \
                                       '{VERSION}.apk"}}}}).include("name", "repo", "path", "created")' \
                                       '.sort({{"$desc": ' '["created"]}}).limit(1)'
ARTIFACTORY_AQL_GET_ALL_NAA_QUERY = 'items.find({{"repo": {{"$eq": "{REPO}"}},{DEBUG_PATH}  "name": ' \
                                    '{{"$match":"NokiaAndroidApplication-vc-*-vn-*.' \
                                    'apk"}}}}).include("name", "repo", "path", "created")' \
                                    '.sort({{"$desc": ["created"]}})'


class AutoUpdater:
    """Class used by AndroidUe to perform automatic update of UE. Requires configuration via yaml file."""

    def __init__(self, ssh_manager, config_reader, serial_number, ue_pc_os, ue_pc_ip, pyro_client):
        """
        Class used by AndroidUe to perform automatic update of UE. Requires configuration via yaml file.
        :param ssh_manager: SshManager object to be used for SFTP and SSH connections
        :param config_reader: config reader pointing to configuration used in test
        :param serial_number: serial number of UE to be updated
        :parm ue_pc_os: OS on UEPC
        :param ue_pc_ip: IP of UEPC
        """
        self._ssh_manager = ssh_manager
        self._config_reader = config_reader
        self._serial_number = serial_number
        self._ue_pc_os = ue_pc_os
        self.update_server_ip = self._config_reader.read_update_server_ip()
        self.logger = logging.getLogger('ute_ue.debug')
        self._versions_on_server = None
        self._version_to_update_to = None
        self._ue_pc_ip = ue_pc_ip
        self._pyro_client = pyro_client
        self._apk_to_update = self._config_reader.read_apk_to_update()
        self._artifactory_url = ARTIFACTORY_URL
        self._artifactory_repo = ARTIFACTORY_REPO
        self._artifactory_aql_suffix = ARTIFACTORY_AQL_SUFFIX
        self._artifactory_user = ARTIFACTORY_USER
        self._artifactory_passwd = ARTIFACTORY_PASSWD
        self._is_debug_allowed = self._config_reader.read_download_debug()
        if self._apk_to_update is None or self._apk_to_update == "UeManager":
            self._artifactory_get_newest_query = ARTIFACTORY_AQL_GET_NEWEST_QUERY
            self._artifactory_get_all_query = ARTIFACTORY_AQL_GET_ALL_QUERY
            self._apk_name = UE_MANAGER_APK_NAME
            self._apk_not_installed = UE_MANAGER_NOT_INSTALLED
            self._apk_package = UE_MANAGER_PACKAGE
            self._apk_name_prefix = UE_MANAGER_NAME_PREFIX
        else:
            self._artifactory_get_newest_query = ARTIFACTORY_AQL_GET_NEWEST_NAA_QUERY
            self._artifactory_get_all_query = ARTIFACTORY_AQL_GET_ALL_NAA_QUERY
            self._apk_name = NAA_APK_NAME
            self._apk_not_installed = NAA_NOT_INSTALLED
            self._apk_package = NAA_PACKAGE
            self._apk_name_prefix = NAA_NAME_PREFIX

    def check_and_perform_update(self):
        """
        Checks whether UeManager on Nokia Android Application application on UE should be updated to specified version in configuration file
        or to newest version if not specified.
        :return:
        """
        try:
            if self.update_server_ip:
                return self._perform_update(preferred_update_method='sftp')
            elif not self._config_reader.read_turn_artifactory_update_off():
                self._read_artifactory_config_options()
                return self._perform_update(preferred_update_method='artifactory')
        except Exception as e:
            self.logger.debug('Exception {} during auto update, it will not be performed.'.format(e))
            return False

        self.logger.debug('Update server ip not provided, auto-update for this UE is off.')
        return True

    def _download_apk_from_artifactory(self, version=None):
        post_result, version = self._get_post_result_with_apk_name_to_download(version)
        self._log_post_result(post_result)
        self._verify_newest_apk_name_post_result(post_result, version)
        apk_name = post_result.json()['results'][0]['name']
        path_to_apk_on_local_machine = os.path.join(os.getcwd(), self._apk_name)
        if 'debug' in apk_name:
            get_binary_apk_result = requests.get(
                url="{}/{}/debug/{}".format(self._artifactory_url, self._artifactory_repo, apk_name), verify=False)
        else:
            get_binary_apk_result = requests.get(
                url="{}/{}/{}".format(self._artifactory_url, self._artifactory_repo, apk_name), verify=False)
        self._log_post_result(get_binary_apk_result)
        self._verify_download_apk_get_result(get_binary_apk_result, version)
        with open(path_to_apk_on_local_machine, 'wb') as f:
            f.write(get_binary_apk_result.content)
            return path_to_apk_on_local_machine

    def _verify_download_apk_get_result(self, get_binary_apk_result, version):
        status_code = get_binary_apk_result.status_code
        if status_code != 200:
            err_msg = 'Status code {} when trying to download {} version {}. Server response:{}'.format(
                status_code, self._apk_name, 'newest' if version == '*' else version,
                get_binary_apk_result.reason)
            self.logger.error(err_msg)
            raise NetworkException(err_msg)

    def _verify_newest_apk_name_post_result(self, post_result, version):
        if post_result.status_code != 200:
            err_msg = 'Status code {} when trying to search for {} version {}. Server response:{}'.format(
                post_result.status_code, self._apk_name, 'newest' if version == '*' else version,
                post_result.reason)
            self.logger.error(err_msg)
            raise NetworkException(err_msg)
        if not post_result.json()['results']:
            err_msg = 'Version {} has not been found on artifactory server!'.format(version)
            self.logger.error(err_msg)
            raise NetworkException(err_msg)

    def _get_post_result_with_apk_name_to_download(self, version):
        repo = self._artifactory_repo
        if not version:
            version = '*'
        else:
            version = version.replace('.', '-')
        if 'debug' in version:
            repo = self._artifactory_repo
            aql_query = self._artifactory_get_newest_query.format(REPO=repo, VERSION=version,
                                                                  DEBUG_PATH=ARTIFACTORY_DEBUG_AQL_FRAGMENT)
        else:
            aql_query = self._artifactory_get_newest_query.format(REPO=repo, VERSION=version, DEBUG_PATH="")
        self.logger.debug('Get apk name to download Artifactory AQL query={}'.format(aql_query))
        self.logger.debug('Trying to download {} version {}'.format(self._apk_name, version))
        post_result = requests.post(url="{}/{}".format(self._artifactory_url, self._artifactory_aql_suffix),
                                    auth=(self._artifactory_user, self._artifactory_passwd),
                                    data=aql_query, verify=False)
        return post_result, version

    def _get_apk_versions_on_artifactory(self):
        data = self._artifactory_get_all_query.format(REPO=self._artifactory_repo, DEBUG_PATH="")
        self.logger.debug('Sending POST to artifactory with AQL query:{}'.format(data))
        post_result = self._send_post_request(url="{}/{}".format(self._artifactory_url, self._artifactory_aql_suffix),
                                              user=self._artifactory_user, passwd=self._artifactory_passwd, data=data)
        self._log_post_result(post_result)
        versions = self._get_versions_from_post_result(post_result)
        if self._is_debug_allowed:
            data = self._artifactory_get_all_query.format(REPO=self._artifactory_repo,
                                                          DEBUG_PATH=ARTIFACTORY_DEBUG_AQL_FRAGMENT)
            self.logger.debug('Sending POST to artifactory with AQL query:{}'.format(data))
            post_result = self._send_post_request(
                url="{}/{}".format(self._artifactory_url, self._artifactory_aql_suffix), user=self._artifactory_user,
                passwd=self._artifactory_passwd, data=data)
            self._log_post_result(post_result)
            versions.extend(self._get_versions_from_post_result(post_result, raise_if_no_versions_found=False))
        return versions

    def _log_post_result(self, post_result):
        status_code = post_result.status_code
        if status_code == 200:
            content = "App .apk file"
        else:
            content = post_result.content
        self.logger.debug(
            "Post result status code:{}\nPost result reason:{}\nPost result content:{}".format(status_code,
                                                                                               post_result.reason,
                                                                                               content))

    def _get_versions_from_post_result(self, post_result, raise_if_no_versions_found=True):
        if post_result.status_code != 200:
            raise InvalidServerResponseException('Status code {} when trying to search for {} on artifactory.'
                                                 ' Server response:{}'.format(post_result.status_code, self._apk_name,
                                                                              post_result.reason))
        if raise_if_no_versions_found and not post_result.json()['results']:
            raise NoSuchVersionOnServerException('No files have been found on artifactory server!')
        versions = [name['name'] for name in post_result.json()['results']]
        return versions

    def _send_post_request(self, url, user, passwd, data):
        return requests.post(url=url, auth=(user, passwd), data=data, verify=False)

    def _perform_update(self, preferred_update_method='sftp'):
        self.logger.debug('Check if {} version is up to date, and update it if needed.'.format(self._apk_name))
        try:
            if self._is_update_needed(preferred_update_method):
                self.logger.debug('Update is needed, performing update to {}'.format(self._version_to_update_to))
                self._update_to_set_version(preferred_update_method)
                return
            self.logger.debug('{} on UE is already {} no need to update.'.format(self._apk_name,
                                                                                 self._version_to_update_to
                                                                                 if self._version_to_update_to
                                                                                 else 'highest possible version'))
            return
        except UeManagerApkUpdateException as e:
            self.logger.error('Auto update error, cause:\n{}'.format(getattr(e, 'message', str(e))))
            self.logger.debug(e, exc_info=True)
            return

    def _update_to_set_version(self, preferred_update_method='sftp'):
        if preferred_update_method == 'sftp':
            self.logger.debug('Pre register new ssh')
            self._register_new_ssh_connection(update_server_ip=self.update_server_ip,
                                              username=self._config_reader.read_update_server_user(),
                                              password=self._config_reader.read_update_user_passwd(),
                                              ssh_key_path=self._config_reader.read_ssh_key_file_path(),
                                              ssh_key_type=self._config_reader.read_ssh_key_type())
            self.logger.debug('pre read update dir')
            update_server_dir = self._config_reader.read_server_update_dir()
            self.logger.debug('pre download file from sftp')
            path_to_apk_on_local_machine = self._download_file_from_sftp_server(update_server_dir)
        else:
            path_to_apk_on_local_machine = self._download_apk_from_artifactory(
                version=self._version_to_update_to)
        path_to_apk_on_uepc = '{}/{}'.format(self._config_reader.read_server_dir(), self._apk_name)
        self._transfer_apk_file_to_uepc(path_to_apk_on_local_machine, path_to_apk_on_uepc)
        if not self._is_apk_on_uepc_accessible(path_to_apk_on_uepc):
            self.logger.debug('Trying to grant permission to {} file'.format(path_to_apk_on_uepc))
            self._pyro_client.set_permissions_to_path_on_uepc(path_to_apk_on_uepc, self._ue_pc_ip,
                                                              reuse_connection=True)
            if not self._is_apk_on_uepc_accessible(path_to_apk_on_uepc):
                raise UeManagerApkUnavailableException("Unable to change {} permissions! Auto update will not perform!"
                                                       .format(path_to_apk_on_uepc))
        self._install_new_apk(path_to_apk_on_uepc)

    def _download_file_from_sftp_server(self, update_server_dir):
        path_to_apk_on_server = '{}/{}'.format(update_server_dir, self._versions_on_server[self._version_to_update_to])
        self.logger.debug('path to apk on server {}'.format(path_to_apk_on_server))
        path_to_apk_on_local_machine = os.path.join(os.getcwd(), self._apk_name)
        self.logger.debug('path to apk on local {}'.format(path_to_apk_on_local_machine))
        self._ssh_manager.transfer_files_from_remote_ssh_host(self.update_server_ip, path_to_apk_on_server,
                                                              path_to_apk_on_local_machine)
        return path_to_apk_on_local_machine

    def _uninstall_current_app(self):
        if self._check_if_app_installed(package_name=NAA_PACKAGE):
            self._ssh_manager.run_cmd_and_get_output_lines(
                'adb -s {} uninstall {}'.format(self._serial_number, NAA_PACKAGE), self._ue_pc_ip,
                reuse_connection=True)
            self.logger.debug('{} uninstalled from {}'.format(NAA_PACKAGE, self._serial_number))

        if self._check_if_app_installed(package_name=UE_MANAGER_PACKAGE):
            self._ssh_manager.run_cmd_and_get_output_lines(
                'adb -s {} uninstall {}'.format(self._serial_number, UE_MANAGER_PACKAGE), self._ue_pc_ip,
                reuse_connection=True)
            self.logger.debug('{} uninstalled from {}'.format(UE_MANAGER_PACKAGE, self._serial_number))

    def _install_new_apk(self, path_to_apk_on_uepc):
        self._uninstall_current_app()

        _, stdout, stderr = self._ssh_manager.run_cmd_and_get_blocking_streams(
            'adb -s {} install -g {}'.format(self._serial_number, path_to_apk_on_uepc), self._ue_pc_ip,
            reuse_connection=True)
        all_lines = []
        stderr_output = stderr.readlines()
        all_lines.extend(stderr_output)
        self.logger.debug('stderr_lines={}'.format(all_lines))
        stdout_output = stdout.readlines()
        all_lines.extend(stdout_output)
        self.logger.debug('stdout_lines_{}'.format(stdout_output))
        for line in all_lines:
            if 'No such file or directory' in line:
                self._ssh_manager.run_cmd_and_get_output_lines('cp {} .'.format(path_to_apk_on_uepc), self._ue_pc_ip,
                                                               reuse_connection=True)
                path_to_apk_on_uepc = self._apk_name
                _, stdout, stderr = self._ssh_manager.run_cmd_and_get_blocking_streams('adb -s {} install -g {}'
                                                                                       .format(self._serial_number,
                                                                                               path_to_apk_on_uepc),
                                                                                       self._ue_pc_ip)

        stderr_output = stderr.readlines()
        stdout_output = stdout.readlines()
        [all_lines.append(line) for line in stdout_output]
        [all_lines.append(line) for line in stderr_output]
        self.logger.debug('stderr_lines={}'.format(all_lines))
        for line in all_lines:
            self.logger.debug('stderr_line:{} Type:{}'.format(line, type(line)))
            if 'Unknown option: -g' in line:
                self.logger.debug("Install with -g switch failed, installing without it.")
                self._ssh_manager.run_cmd_and_get_output_lines(
                    'adb -s {} install {}'.format(self._serial_number, path_to_apk_on_uepc),
                    self._ue_pc_ip, reuse_connection=True)
        self.logger.debug('{} installed on {}'.format(self._apk_name, self._serial_number))

    def _transfer_apk_file_to_uepc(self, path_to_apk_on_local_machine, path_to_apk_on_uepc):
        self._ssh_manager.transfer_file_to_remote_ssh_host(self._ue_pc_ip, path_to_apk_on_local_machine,
                                                           path_to_apk_on_uepc)

    def _get_version_file_mapping(self, version_files, apk_name_prefix):
        version_dict = {}
        if not self._is_debug_allowed:
            version_files = [version for version in version_files if "debug" not in version.lower()]
        version_files = [version for version in version_files if
                         version.startswith(apk_name_prefix) and version.endswith('.apk')]
        for version in version_files:
            remote_version = version.split('vn-')[1][:-4]
            remote_version = remote_version.replace('-', '.')
            remote_version = remote_version.replace('.debug', '-debug')
            version_dict[remote_version] = version
        return version_dict

    def _is_update_needed(self, preferred_update_method='sftp'):
        version_on_ue = self._get_mobile_version_via_adb()
        self._version_to_update_to = self._config_reader.read_desired_app_version()
        if preferred_update_method == 'sftp':
            self.logger.debug('Using sftp server for update')
            server_dir = self._config_reader.read_server_update_dir()
            self._register_ssh_connection_to_sftp()
            version_files = self._get_sftp_server_version_files(server_dir)
        else:
            self.logger.debug('Using artifactory server for update')
            version_files = self._get_apk_versions_on_artifactory()
            self.logger.debug('Application version files: {}'.format(version_files))
        return self._check_if_update_is_needed(self._version_to_update_to, preferred_update_method,
                                               version_on_ue,
                                               version_files)

    def _register_ssh_connection_to_sftp(self):
        self._register_new_ssh_connection(update_server_ip=self.update_server_ip,
                                          username=self._config_reader.read_update_server_user(),
                                          password=self._config_reader.read_update_user_passwd(),
                                          ssh_key_path=self._config_reader.read_ssh_key_file_path(),
                                          ssh_key_type=self._config_reader.read_ssh_key_type())

    def _get_sftp_server_version_files(self, server_dir):
        ls_cmd = 'ls {}'.format(server_dir)
        version_files = self._ssh_manager.run_cmd_and_get_output_lines(cmd=ls_cmd, hostname=self.update_server_ip,
                                                                       reuse_connection=True)
        return version_files

    def _check_if_update_is_needed(self, desired_version, preferred_update_method, apk_version_on_ue,
                                   version_files):
        if not version_files:
            self.logger.error('Couldn\'t find any apk files on {}'.format(preferred_update_method))
            return False
        self.logger.debug('Version files pre _get_version_file_mapping={}'.format(version_files))
        if self._apk_to_update is None:
            apk_name_prefix = UE_MANAGER_NAME_PREFIX
        else:
            apk_name_prefix = NAA_NAME_PREFIX
        self.logger.debug('Application name is {}'.format(apk_name_prefix))
        self._versions_on_server = self._get_version_file_mapping(version_files, apk_name_prefix)
        if not desired_version:
            newest_version = self._get_highest_version_from_list(self._versions_on_server.keys(),
                                                                 is_debug_allowed=self._is_debug_allowed)
            self._version_to_update_to = newest_version
            self.logger.debug(
                'No version specified in config file, should update to newest available version - {}'.format(
                    newest_version))
            return apk_version_on_ue == self._apk_not_installed or self._is_version_lower(
                apk_version_on_ue, newest_version, is_debug_allowed=self._is_debug_allowed)
        if desired_version in self._versions_on_server or desired_version.encode('utf-8') in self._versions_on_server:
            self._version_to_update_to = desired_version
            self.logger.debug('Should update to {}'.format(self._version_to_update_to))
            return apk_version_on_ue != desired_version
        self.logger.error('Version {} is not present on update server! Possible versions:{}'.format(
            desired_version, self._versions_on_server.keys()))
        return False

    def _register_new_ssh_connection(self, update_server_ip, username, password=None, ssh_key_path=None,
                                     ssh_key_type=None):
        self._ssh_manager.register(hostname=update_server_ip, username=username, password=password,
                                   ssh_key_path=ssh_key_path, ssh_key_type=ssh_key_type)

    def _get_mobile_version_via_adb(self):
        find_string_cmd = utils.ShellCommands.FIND_STRING[self._ue_pc_os]
        version_name_param = 'versionName'
        adb_cmd = 'adb -s {ue_serial_number} shell dumpsys package {package_name} | {findstr_command}"{version_name}"'. \
            format(ue_serial_number=self._serial_number, package_name=self._apk_package,
                   findstr_command=find_string_cmd,
                   version_name=version_name_param)
        self.logger.debug('Getting {} version via adb...'.format(self._apk_name))
        output_lines = self._ssh_manager.run_cmd_and_get_output_lines(adb_cmd, self._ue_pc_ip, reuse_connection=True)
        for line in output_lines:
            line = line.strip()
            if '=' in line:
                apk_version = line.split('=')[1]
                self.logger.debug('{} version on UE = {}'.format(self._apk_name, apk_version))
                return apk_version
        return self._apk_not_installed

    def _read_artifactory_config_options(self):
        self._artifactory_url = self._artifactory_url if self._config_reader.read_artifactory_url() is None \
            else self._config_reader.read_artifactory_url()
        self._artifactory_repo = self._artifactory_repo if self._config_reader.read_artifactory_repository() is None \
            else self._config_reader.read_artifactory_repository()
        self._artifactory_user = self._artifactory_user if self._config_reader.read_update_server_user() is None \
            else self._config_reader.read_update_server_user()
        self._artifactory_passwd = self._artifactory_passwd if self._config_reader.read_update_user_passwd() is None \
            else self._config_reader.read_update_user_passwd()

    def _check_if_app_installed(self, package_name):
        find_string_cmd = utils.ShellCommands.FIND_STRING[self._ue_pc_os]
        version_name_param = 'versionName'
        adb_cmd = 'adb -s {ue_serial_number} shell dumpsys package {package_name} | {findstr_command}"{version_name}"'. \
            format(ue_serial_number=self._serial_number, package_name=package_name, findstr_command=find_string_cmd,
                   version_name=version_name_param)
        return True if self._ssh_manager.run_cmd_and_get_output_lines(
            adb_cmd, self._ue_pc_ip, reuse_connection=True) is not None else False

    def _get_highest_version_from_list(self, version_list, is_debug_allowed=False):
        if is_debug_allowed:
            return self._get_highest_version_from_release_and_debug_versions(version_list)
        version_list = [version for version in version_list if "debug" not in version.lower()]
        return max(version_list)

    def _get_highest_version_from_release_and_debug_versions(self, version_list):
        release_versions = [version for version in version_list if "debug" not in version.lower()]
        debug_versions = [version for version in version_list if "debug" in version.lower()]
        highest_release_version = max(release_versions)
        if not debug_versions:
            return highest_release_version
        debug_versions = AutoUpdater._strip_debug_from_version(debug_versions)
        highest_debug_version = max(debug_versions)
        highest_debug_version = highest_debug_version + '-debug'
        if self._is_version_lower(highest_release_version, highest_debug_version, True):
            return highest_debug_version
        return highest_release_version

    @staticmethod
    def _strip_debug_from_version(debug_versions):
        return [version.strip("-debug") for version in debug_versions]

    def _is_version_lower(self, apk_version_on_ue, newest_version, is_debug_allowed=False):
        self.logger.debug("Comparing ue version: {} and server version:{}".format(apk_version_on_ue, newest_version))
        if 'debug' in newest_version.lower() and not is_debug_allowed:
            return False
        if 'debug' in apk_version_on_ue.lower() and not is_debug_allowed:
            return True

        debug_add_one = 0

        ue_version = [x for x in apk_version_on_ue.split('.')]
        ue_version[2] = ue_version[2].rstrip('-debug')
        server_version = [x for x in newest_version.split('.')]
        server_version[2] = server_version[2].rstrip('-debug')
        are_versions_different = apk_version_on_ue != newest_version.strip('-debug')
        if not are_versions_different and is_debug_allowed and 'debug' in newest_version.lower():
            debug_add_one += 1
        major = int(ue_version[0]) >= int(server_version[0])
        minor = int(ue_version[1]) >= int(server_version[1])
        hotfix = int(ue_version[2]) >= int(server_version[2]) + debug_add_one
        return are_versions_different and not (major and minor and hotfix)

    def _is_apk_on_uepc_accessible(self, path_to_apk_on_uepc):
        self.logger.debug('Checking if apk downloaded to uepc is available at path {}'.format(path_to_apk_on_uepc))
        cmd_for_checking_access = 'head -1 {path_to_apk} 2>&1> /dev/null'.format(path_to_apk=path_to_apk_on_uepc)
        check_access_result = self._ssh_manager.run_cmd_and_get_output_lines(cmd_for_checking_access, self._ue_pc_ip,
                                                                             reuse_connection=True)
        self.logger.debug('Result of checking access = {}'.format(check_access_result))
        if 'Permission denied' in check_access_result:
            self.logger.debug('AutoUpdater has no permission for file {}.'.format(path_to_apk_on_uepc))
            return False
        if 'No such file or directory' in check_access_result:
            self.logger.error('AutoUpdater unable to find {} on UEPC, reason:{}\nAuto update will not be performed, '
                              'test will continue on older apk.'.format(path_to_apk_on_uepc, check_access_result))
            raise UeManagerApkUnavailableException(
                "Tried to access downloaded UeManager.apk at {} but failed with error:{}".format(path_to_apk_on_uepc,
                                                                                                 check_access_result))
        return True
